"""Local HTTP classroom sequence; shared runnable service is packaged separately."""
from write_media_data_network import entry, emit, task, question

SCOPE='使用随课Python课堂服务，HostBox只填电脑局域网IPv4。示例不是公网服务；手机上的127.0.0.1指手机自身。服务的自动测试不等于Android客户端真机联调。'
STATES=[['请求中','假；一次只发一个请求'],['当前URL','发起时保存；回调需核对'],['HostBox','只填IP，端口8765由积木拼接']]

entry(37,SCOPE+' 本课读取纯文本，不解码JSON；HTTP 404仍属于收到服务器响应。',STATES,
 ['合法主机地址组合路径，请求前锁定按钮','GotText检查当前URL与状态码','成功、HTTP错误、超时均结束请求并恢复操作'],
 [task('补请求过程',['找到请求文本过程，保留已有URL拼接。','请求中真，禁用两个请求按钮。','设置Http.Url为当前URL并调用Get。','连续点击不重复发送。'],'Get返回时已经拿到文本了吗？','没有，结果通过稍后的GotText或TimedOut事件到达。'),
  task('补文本回调',['添加Http.GotText，只处理当前请求URL。','responseCode=200才显示responseContent。','其他码显示HTTP编号，不把错误页当问候。','最后调用结束请求恢复按钮。'],'404与超时有什么不同？','404有HTTP响应但路径不存在；超时是在指定等待时间内未完成请求。'),
  task('补超时与异常恢复',['添加Http.TimedOut并核对url。','Screen1.ErrorOccurred也恢复请求状态。','用服务delay场景产生受控延迟，恢复normal后再请求。','不需要物理断网来做此课堂实验。'],'为什么异常分支也要启用按钮？','否则界面会一直停在请求中，用户无法纠正地址或重新请求。')],
 [question('手机里localhost指哪台设备？','指手机自己，不能代替电脑服务地址。'),question('200与404分别说明什么？','200成功返回；404是服务器找不到请求路径。'),question('请求中标志何时恢复？','成功、HTTP错误、超时及通信异常的结束路径都要恢复。')],
 ['保留路径参数，HostBox不填协议或端口。请求前更新状态。','当前URL核对避免把其他响应当成本次结果；这里只显示文本。','超时是异步事件，应恢复按钮并给出可操作提示。'])

entry(38,SCOPE+' 使用JsonTextDecodeWithDictionaries。缺字段、空列表和null均须做类型保护；不混用旧版列表对解码结构。',STATES+[['公告数据','顶层字典，内部包含列表和字典']],
 ['200文本解码，先检查顶层字典','按键取announcements，确认非空后取首项','缺班名使用默认，空公告和坏活动类型有可读反馈'],
 [task('补解码与顶层检查',['在GotText的200分支解码responseContent。','确认返回值是字典才调用显示公告。','非200与坏JSON使用已有恢复入口。'],'JSON看起来像文字，为什么不能直接按键读？','HTTP返回的是文本，需要先解码成字典或列表结构。'),
  task('补嵌套公告与活动',['取announcements，先检查是列表且长度大于0。','再检查首项字典，按title键显示。','activities为列表才赋Elements，否则用空列表。'],'空公告能直接取第1项吗？','不能，先判空，空列表显示暂无公告。'),
  task('检验默认值与null',['Class已给className默认读取，补类型检查。','缺失或null时显示未命名班级。','启动服务empty场景，正常请求按钮即可观察空内容。','恢复normal，确认界面能重新显示公告。'],'空数据和网络失败如何区分？','成功响应中的空列表可显示暂无内容；状态码或通信失败另报原因。')],
 [question('本课为何选WithDictionaries解码？','对象直接变字典，能按字段键读取。'),question('读取首项前做什么检查？','确认是列表且非空，再确认项目类型。'),question('activities=null能赋给Elements吗？','不直接赋，类型不符时改用空列表。')],
 ['只在200分支解码并检查顶层类型；错误恢复结构已给。','字典→公告列表→首项字典→title，逐层检查。','按钮和请求过程已给；空数据场景由服务启动参数选择。'],
 block_body={2:['服务用empty场景返回空公告。','普通请求按钮无需修改URL。']})

entry(39,SCOPE+' 查询教师提供的校园地点示例，不访问真实地图或采集位置。显示名称与原始字典保持同序。',STATES+[['地点结果','响应items列表；新查询会替换旧结果']],
 ['trim非空关键词，用UriEncode编码参数值','200解码items后重建名称列表并清旧详情','有效选择读取对应地点的楼层与说明'],
 [task('补查询编码',['在查询地点中校验trim关键词非空。','只对参数值调用Http.UriEncode。','拼接/api/v1/places?q=与编码结果，再Get。','中文图书前后加空格仍应查询图书角。'],'可以把整个URL都UriEncode吗？','不应，协议和路径分隔符要保留，只编码查询参数值。'),
  task('核对结果刷新与空表',['阅读已给显示地点结果主体。','新结果先清详情、取消旧选择。','确认名称列表与地点字典列表顺序一致。','0项时显示数量0，不继续显示旧地点。'],'名称列表能单独排序而不调整原数据吗？','不能直接这样做，否则同一索引会指向不同地点。'),
  task('补选择详情',['添加PlacesView.AfterPicking，校验索引。','按同一位置取地点字典。','读name、floor、note并组成详情。','先选正常结果，再查不存在，核对详情清空。'],'SelectionIndex=0时为何不取记录？','0表示无有效选择，读取会越界。')],
 [question('UriEncode解决什么问题？','把中文及特殊字符安全放入参数值。'),question('空关键词是否发请求？','本例不发，先提示输入查询内容。'),question('空结果时旧详情怎么办？','清空并显示0项，避免误导。')],
 ['编码的是trim后的参数值，不是整个URL。','保留完整字典列表，仅取name生成显示列表。','有效索引先于取字典，空结果不沿用旧详情。'])

entry(40,SCOPE+' POST发送教学意见，不要求真实姓名或联系方式。超时表示结果未确认，本例不自动重发。',STATES+[['类型','建议／问题／表扬'],['正文','trim后1到200字符']],
 ['校验正文，设置表单Content-Type','BuildRequestData编码kind和message后PostText','201有效回执才清稿，400或超时保留草稿'],
 [task('补校验与请求头',['trim正文，长度须为1到200。','设置RequestHeaders的Content-Type为application/x-www-form-urlencoded。','请求中真并禁用发送按钮。'],'为什么不能把空输入发给服务器再说？','客户端先反馈可减少无效请求，服务端仍需独立校验。'),
  task('补表单编码与成功回执',['BuildRequestData处理kind和message两组键值。','PostText发送到/api/v1/feedback。','GotText只在201且回执id有效时显示已接收并清正文。','编号可能已增长，不硬编码F0001。'],'只检查HTTP 201就能忽略回执结构吗？','不应，还要确认返回数据含有效id再显示本次成功。'),
  task('保留失败草稿',['400和其他失败只显示原因、恢复按钮。','超时保留正文并提示结果未确认。','重新提交前先核对服务记录，不自动再次Post。'],'超时为何不能直接说提交失败？','请求可能已被服务器保存，只是回执没及时回来。')],
 [question('BuildRequestData的作用是什么？','按表单规则编码键值，保护中文和特殊字符。'),question('何时清草稿？','成功201且有效回执确认之后。'),question('POST超时为何不自动重试？','可能造成同一意见重复提交。')],
 ['输入校验先于请求状态切换；表单头与编码方式一致。','201分支解码id，错误分支保留输入。','超时处理报告未确认并恢复操作，不调用PostText。'])

entry(41,SCOPE+' 同一课堂服务共享最近50条留言。仅用课堂昵称，示例没有账号、权限或公开审核系统。',STATES+[['操作','读取／发布；用于解释GotText'],['留言','完整字典列表，与摘要同序']],
 ['发布先校验昵称和正文，再编码表单','同一GotText按操作区分POST 201和GET 200','发布确认后只自动GET刷新，选择摘要能读完整内容'],
 [task('阅读公共读取并补发布',['保留已给读取留言过程。','发布昵称trim后1到12字符，正文1到120字符。','设置操作发布、禁用两键，编码nick和message后PostText。'],'两台手机为什么必须填同一个电脑地址？','共同访问同一个服务才能读取同一份留言数据。'),
  task('补发布响应分支',['GotText先看操作与状态码。','发布201且id有效才清正文。','结束该发布状态，再调用读取留言Get刷新。','读取200才解析items；失败保留草稿。'],'发布后刷新会不会再次发布？','不会，刷新走Get；不能再次调用发布留言过程。'),
  task('互测摘要与详情',['阅读已给MessagesView.AfterPicking。','按索引显示nick、完整message、id、createdAt。','课堂两端一端发、一端刷新，对比同一id。','说明50条保留政策和服务时间来源。'],'列表摘要被截短是否代表正文丢失？','不代表，完整正文仍在字典中，详情应读原字段。')],
 [question('操作变量为什么需要？','同一Web组件回调要区分读取和发布响应。'),question('发布成功后的自动动作是什么？','仅Get读取新列表，不重发Post。'),question('服务时间等于手机本地时间吗？','不一定，createdAt来自服务端，界面应标明来源。')],
 ['读取已给，发布过程待补；两按钮在请求中都禁用。','按操作区分201与200，发布确认后读取，不自动再次Post。','详情入口已给，使用同序索引和完整字典字段。'])

entry(42,SCOPE+' 缓存仅代表最后一次有效接收，必须显示本机缓存及可能过时。受控delay/error/invalid-json场景用于课堂排错，不要求物理断网测试。',STATES+[['缓存数据','最后通过结构校验的公告字典'],['缓存时间','本机接收时间，保存为savedAt']],
 ['启动先读TinyDB缓存，明确来源','刷新等待；200也要先验证结构','成功再覆盖缓存，失败保留旧值并恢复按钮'],
 [task('阅读启动缓存并补刷新',['追踪载入缓存和已有结构验证。','无有效缓存显示尚无资料。','补刷新公告：请求中真、禁用按钮、保存URL、Get。'],'有缓存为何仍需标来源和时间？','旧资料可能过时，不能让用户误以为刚从网络取得。'),
  task('补成功更新',['先调用公告结构有效检查字段和类型。','通过后才替换缓存变量，生成本机接收时间。','TinyDB写info与savedAt，再显示本次网络结果。','坏结构不得覆盖已有好缓存。'],'HTTP 200能证明内容结构正确吗？','不能，状态成功与业务数据可用需要分别检查。'),
  task('补失败恢复',['有好缓存则继续显示并标可能过时。','无缓存则保持尚无资料，显示失败原因。','恢复请求中假及按钮可用。','用error或invalid-json场景验证，恢复normal后重试。'],'失败时为什么不把空字典存回缓存？','会毁掉最后一份可用数据；失败只改变状态提示。')],
 [question('缓存时间代表什么？','本机最后成功接收并保存的时刻，不冒充服务器更新时间。'),question('坏JSON应覆盖旧缓存吗？','不应，解析或结构验证失败应保留旧缓存。'),question('怎样重复制造超时？','把课堂服务启动为delay场景，再用原请求按钮。')],
 ['启动读取info与savedAt；显示缓存来源，不自动假装新数据。','先验证再更新变量和TinyDB，坏结构分支不写入。','恢复按钮并保留缓存内容，提示原因和可能过时。'])

